// The extra generated file of a module that embeds compiled stylesheets (issue #81, ADR-048): the
// serializer output of every embedded sheet as `inline constexpr` byte arrays plus the registration
// table startup consumes (docs/specs/compiled-stylesheet-v1.md section 9).

#include "codegen_internal.hpp"

#include <cctype>
#include <cstddef>
#include <cstdint>
#include <string>
#include <string_view>

namespace tessera::compiler::codegen::internal {
namespace {

constexpr std::size_t kBytesPerLine = 12;
constexpr char kHexDigits[] = "0123456789abcdef";

std::string byte_text(std::uint8_t value) {
    std::string text("0x");
    text += kHexDigits[(value >> 4U) & 0xFU];
    text += kHexDigits[value & 0xFU];
    return text;
}

// A project path is POSIX, but a quote or a backslash in a file name must still not break the
// generated string literal.
std::string escaped(std::string_view text) {
    std::string out;
    out.reserve(text.size());
    for (const char c : text) {
        if (c == '\\' || c == '"') {
            out += '\\';
        }
        out += c;
    }
    return out;
}

} // namespace

std::string stylesheet_identifier(std::string_view id) {
    std::string name;
    name.reserve(id.size());
    bool separator = false;
    for (const char c : id) {
        if (std::isalnum(static_cast<unsigned char>(c)) != 0) {
            name += c;
            separator = false;
        } else if (!separator) {
            // A run of non-alphanumerics is one `_`: `css::ui/app` -> `css_ui_app`.
            name += '_';
            separator = true;
        }
    }
    return name;
}

std::string emit_stylesheet_header(std::string_view module_name,
                                   std::span<const ResolvedStylesheet> sheets) {
    CppWriter writer;
    writer.line("// Generated by tessera_codegen. Do not edit.");
    writer.line("// Embedded stylesheet blobs (docs/specs/compiled-stylesheet-v1.md): load with");
    writer.line("// tessera::ui::style::load_stylesheet_blob at startup.");
    writer.line("#pragma once");
    writer.line("#include <array>");
    writer.line("#include <cstdint>");
    writer.line("#include <span>");
    writer.line("#include <string_view>");
    writer.open("namespace " + std::string(module_name));

    for (std::size_t i = 0; i < sheets.size(); ++i) {
        const ResolvedStylesheet& sheet = sheets[i];
        // The first array follows the namespace opening directly; later ones are separated from the
        // previous declaration by one blank line.
        if (i != 0) {
            writer.text += '\n';
        }
        writer.line("inline constexpr std::array<std::uint8_t, " +
                    std::to_string(sheet.bytes.size()) + "> kStylesheetBlob_" +
                    stylesheet_identifier(sheet.id) + " = {");
        ++writer.indent;
        std::string line_text;
        for (std::size_t byte = 0; byte < sheet.bytes.size(); ++byte) {
            line_text += byte_text(sheet.bytes[byte]);
            line_text += ", ";
            if ((byte + 1) % kBytesPerLine == 0) {
                line_text.pop_back(); // the line keeps its trailing comma, not the space
                writer.line(line_text);
                line_text.clear();
            }
        }
        if (!line_text.empty()) {
            line_text.pop_back();
            writer.line(line_text);
        }
        --writer.indent;
        writer.line("};");
    }

    writer.text += '\n';
    writer.open("struct EmbeddedStylesheet");
    writer.line("std::string_view path;");
    writer.line("std::span<const std::uint8_t> bytes;");
    writer.close(";");
    writer.line("inline constexpr std::array<EmbeddedStylesheet, " + std::to_string(sheets.size()) +
                "> kEmbeddedStylesheets = {{");
    ++writer.indent;
    for (const ResolvedStylesheet& sheet : sheets) {
        writer.line("{ \"" + escaped(sheet.path) + "\", kStylesheetBlob_" +
                    stylesheet_identifier(sheet.id) + " },");
    }
    --writer.indent;
    writer.line("}};");
    writer.close(" // namespace " + std::string(module_name));
    return writer.text;
}

} // namespace tessera::compiler::codegen::internal
